<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin-auth' })
const { data: session } = await useFetch<any>('/api/admin/auth/session')
const { data: refunds, refresh } = await useFetch<any[]>('/api/admin/refunds')
const form = reactive({ orderNumber: '', amount: 0, reason: '', recipient: '' })
const message = ref('')
const createRefund = async () => { try { await $fetch('/api/admin/refunds', { method: 'POST', body: form }); message.value = 'Pengajuan refund tersimpan.'; await refresh() } catch (error: any) { message.value = error?.data?.statusMessage || 'Pengajuan gagal.' } }
const action = async (refund: any, action: 'approve' | 'complete') => { const transferReference = action === 'complete' ? prompt('Nomor referensi transfer') || '' : undefined; try { await $fetch(`/api/admin/refunds/${refund.id}`, { method: 'PATCH', body: { action, transferReference } }); await refresh() } catch (error: any) { message.value = error?.data?.statusMessage || 'Perubahan gagal.' } }
const formatPrice = (price: number) => new Intl.NumberFormat('id-ID').format(price)
</script>
<template><div class="admin-page"><div class="admin-page-heading"><div><p class="eyebrow">Finance operation</p><h1>Refund.</h1></div></div><section class="admin-panel"><form class="admin-form" @submit.prevent="createRefund"><div class="admin-form-grid"><label>Nomor order<input v-model="form.orderNumber" required /></label><label>Nominal<input v-model.number="form.amount" required min="1" type="number" /></label></div><label>Alasan<textarea v-model="form.reason" required /></label><label>Data penerima transfer<input v-model="form.recipient" required /></label><button class="button button-dark">Ajukan refund</button><p v-if="message" role="status">{{ message }}</p></form></section><section class="admin-panel"><table class="admin-table"><thead><tr><th>Order</th><th>Nominal</th><th>Alasan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="refund in refunds" :key="refund.id"><td>{{ refund.orderNumber }}</td><td>Rp {{ formatPrice(refund.amount) }}</td><td>{{ refund.reason }}</td><td>{{ refund.status }}</td><td><button v-if="session?.user?.role === 'super_admin' && refund.status === 'requested'" class="admin-row-action" @click="action(refund, 'approve')">Setujui</button><button v-if="session?.user?.role === 'super_admin' && refund.status === 'approved'" class="admin-row-action" @click="action(refund, 'complete')">Catat transfer</button></td></tr></tbody></table></section></div></template>
